<?php
namespace App\Filament\Resources;
use App\Filament\Resources\WaterPurifierResource\Pages;use App\Models\{Customer,Product};use Filament\Resources\Forms\Components;use Filament\Resources\Forms\Form;use Filament\Resources\Resource;use Filament\Resources\Tables\Columns;use Filament\Resources\Tables\Filter;use Filament\Resources\Tables\RecordActions;use Filament\Resources\Tables\Table;
class WaterPurifierResource extends Resource{public static $icon='heroicon-o-cube';public static $label='Sản phẩm của khách hàng';public static $navigationLabel='Sản phẩm của khách hàng';public static $navigationSort=30;
public static function form(Form $f){$products=Product::orderBy('name')->get()->mapWithKeys(fn($p)=>[$p->id=>$p->name.' — '.$p->sku.($p->brand_name?' — '.$p->brand_name:'')])->toArray();return$f->schema([Components\FileUpload::make('image_path')->label('Ảnh thực tế của sản phẩm')->image()->disk('public')->directory('water-purifiers')->maxSize(5120)->imagePreviewHeight(180),Components\Select::make('customer_id')->label('Khách hàng sở hữu')->options(Customer::pluck('full_name','id')->toArray())->required()->dependable(),Components\Select::make('product_id')->label('Sản phẩm khách hàng sử dụng')->options($products)->required()->helpMessage('Chọn sản phẩm đã bán, bàn giao hoặc đang được khách hàng sử dụng.'),Components\Textarea::make('installation_address')->label('Địa chỉ sử dụng sản phẩm')->placeholder('Tự điền theo địa chỉ mặc định hoặc nhập địa chỉ sử dụng thực tế')->helpMessage('Có thể chỉnh lại nếu sản phẩm được sử dụng tại địa chỉ khác.')->required(),Components\TextInput::make('serial_number')->label('Serial / mã định danh')->placeholder('Không bắt buộc nếu sản phẩm không có serial'),Components\DatePicker::make('installed_at')->label('Ngày bàn giao / bắt đầu sử dụng'),Components\DatePicker::make('purchased_at')->label('Ngày mua hàng'),Components\TextInput::make('water_input_tds')->label('TDS nước đầu vào (nếu áp dụng)')->numeric(),Components\TextInput::make('water_output_tds')->label('TDS nước đầu ra (nếu áp dụng)')->numeric(),Components\Select::make('status')->label('Tình trạng sử dụng')->options(['active'=>'Đang sử dụng','inactive'=>'Ngừng sử dụng','replaced'=>'Đã thay thế','disposed'=>'Đã thanh lý'])->default('active')->required(),Components\Textarea::make('note')->label('Ghi chú về sản phẩm')->placeholder('Tình trạng, vị trí sử dụng hoặc thông tin cần lưu ý')]);}
public static function table(Table $t){return$t->columns([Columns\Image::make('image_path')->label('Ảnh')->disk('public')->size(52),Columns\Text::make('customer.full_name')->label('Khách hàng sở hữu')->searchable(),Columns\Text::make('product.name')->label('Sản phẩm')->searchable(),Columns\Text::make('product.brand_name')->label('Thương hiệu'),Columns\Text::make('serial_number')->label('Serial / mã định danh')->searchable(),Columns\Text::make('installation_address')->label('Địa chỉ sử dụng')->limit(30)->searchable(),Columns\Text::make('water_input_tds')->label('TDS đầu vào'),Columns\Text::make('water_output_tds')->label('TDS đầu ra'),Columns\Text::make('last_service_at')->label('Dịch vụ gần nhất')->date('d/m/Y'),Columns\Text::make('next_service_at')->label('Dịch vụ tiếp theo')->date('d/m/Y'),Columns\Text::make('status')->label('Tình trạng sử dụng')->getValueUsing(fn($record)=>(string)$record->status)->options(['active'=>'Đang sử dụng','inactive'=>'Ngừng sử dụng','replaced'=>'Đã thay thế','disposed'=>'Đã thanh lý'])])->filters([Filter::make('active',fn($q)=>$q->where('status','active'))->label('Đang sử dụng'),Filter::make('due',fn($q)=>$q->whereDate('next_service_at','<=',today()))->label('Đến hạn dịch vụ')])->pushRecordActions([RecordActions\Link::make('history')->label('Xem lịch sử')->url(fn($record)=>static::generateUrl('history',['record'=>$record]))]);}
public static function relations(){return[];}public static function historyRelations(){return[\App\Filament\Resources\WaterPurifier\RelationManagers\PurifierFiltersRelationManager::class,\App\Filament\Resources\WaterPurifier\RelationManagers\FilterReplacementHistoriesRelationManager::class,\App\Filament\Resources\WaterPurifier\RelationManagers\ServiceOrdersRelationManager::class];}public static function routes(){return[Pages\ListWaterPurifiers::routeTo('/','index'),Pages\CreateWaterPurifier::routeTo('/create','create'),Pages\EditWaterPurifier::routeTo('/{record}/edit','edit'),Pages\WaterPurifierHistory::routeTo('/{record}/history','history')];}}
